 * Open an authenticated SSE stream. Pairs the two things every SSE consumer must
 * get right and would otherwise duplicate: minting a fresh `?token=` ticket (so
 * embedded-iframe streams authenticate without a cookie) and opening with
 * `withCredentials: true` (so normal-web streams send the session cookie).
 * Lifecycle (reconnect, queueing, abort) stays with the caller — those differ
 * per consumer, so this deliberately does NOT own them.
 */
export async function openSseStream(
  sseUrl: string,
  opts?: { throwOnFailure?: boolean }
): Promise<EventSource> {
  const url = await withSseTicket(sseUrl, opts);
  return new EventSource(url, { withCredentials: true });
}

export type ApiOrgContext = {
  organizationId?: string | null;
  slug?: string | null;
};

export function normalizeOrgContext(orgContext?: ApiOrgContext | string | null): {
  organizationId: string | null;
  slug: string | null;
} {
  if (typeof orgContext === 'string') {
    return { organizationId: orgContext, slug: null };
  }
  return {
    organizationId: orgContext?.organizationId ?? null,
    slug: orgContext?.slug ?? null,
  };
}

export function getPathScope(): { slug: string | null } {
  return { slug: resolveUrlOrgSlug() };
}

/**
 * Resolve the org slug for an API call — explicit orgContext first, then the
 * URL path / subdomain scope — returning `null` when nothing is resolvable
 * yet. Non-throwing, so it's safe to call during render (e.g. to build a query
 * key). Use `resolveApiScope` when a slug is *required* (request URLs) and its
